PREFIX wm: <https://wealth.example.org/ontology/>
PREFIX kg: <https://wealth.example.org/kg/>
PREFIX wmmeta: <https://wealth.example.org/metadata/>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX schema1: <http://schema.org/>
PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>

SELECT ?timeHorizon
       (SUM(xsd:decimal(?cashAmount)) AS ?totalCashFlow)
       (AVG(xsd:decimal(?scenarioChange)) AS ?avgScenarioChange)
       (AVG(xsd:decimal(?allocPct)) AS ?avgAllocationPct)
       (SUM(xsd:decimal(?sectorInvest)) AS ?totalSectorInvestment)
WHERE {
  # Cash Flow aggregation per investor
  {
    SELECT ?timeHorizon ?cashAmount
    WHERE {
      ?inv a wm:Investor ;
           wm:timeHorizon ?timeHorizon ;
           wm:hasCashFlow ?cf .
      ?cf wm:amount ?cashAmount .
    }
  }
  # Scenario Rebalancing change per investor
  OPTIONAL {
    SELECT ?timeHorizon ?scenarioChange
    WHERE {
      ?inv a wm:Investor ;
           wm:timeHorizon ?timeHorizon ;
           wm:hasScenarioRebalancing ?sr .
      ?sr wm:newAllocationPct ?newPct ;
          wm:currentAllocationPct ?curPct .
      BIND (xsd:decimal(?newPct) - xsd:decimal(?curPct) AS ?scenarioChange)
    }
  }
  # Sector Allocation concentration per investor
  OPTIONAL {
    SELECT ?timeHorizon ?allocPct
    WHERE {
      ?inv a wm:Investor ;
           wm:timeHorizon ?timeHorizon ;
           wm:hasSectorAllocation ?sa .
      ?sa wm:allocationPct ?allocPct .
    }
  }
  # Sector investment (totalInvestment) per investor
  OPTIONAL {
    SELECT ?timeHorizon ?sectorInvest
    WHERE {
      ?inv a wm:Investor ;
           wm:timeHorizon ?timeHorizon ;
           wm:hasSectorAllocation ?sa .
      ?sa wm:totalInvestment ?sectorInvest .
    }
  }
}
GROUP BY ?timeHorizon
ORDER BY ?timeHorizon

