PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>

SELECT ?riskTolerance
       (SUM(?holdingGain) AS ?totalHoldingGain)
       (SUM(?rebalanceAmt) AS ?totalRebalancingAmount)
       (SUM(?scenarioChange) AS ?totalScenarioChange)
       (SUM(?cashFlowAmt) AS ?totalCashFlow)
WHERE {
  # Investor and its risk tolerance
  ?inv a wm:Investor ;
       wm:investorId ?invId ;
       wm:riskTolerance ?riskTolerance .

  # Holding gain per investor
  OPTIONAL {
    SELECT ?invId (SUM(xsd:decimal(?gain)) AS ?holdingGain) WHERE {
      ?h a wm:PortfolioHolding ;
         wm:investorId ?invId ;
         wm:currentValue ?curr ;
         wm:cost ?cost .
      BIND (xsd:decimal(?curr) - xsd:decimal(?cost) AS ?gain)
