  }

  # Rebalancing amount per investor
  OPTIONAL {
    SELECT ?invId (SUM(xsd:decimal(?amt)) AS ?rebalanceAmt) WHERE {
      ?ra a wm:RebalancingAction ;
          wm:investorId ?invId ;
          wm:amount ?amt .
    } GROUP BY ?invId
  }

  # Scenario allocation change per investor
  OPTIONAL {
    SELECT ?invId (SUM(xsd:decimal(?change)) AS ?scenarioChange) WHERE {
      ?sr a wm:ScenarioRebalancing ;
          wm:investorId ?invId ;
