PREFIX schema1: <http://schema.org/>
PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>

SELECT ?investorId ?investorName ?totalCashFlow ?avgProgress WHERE {
  {
    SELECT ?investor (SUM(xsd:decimal(?amount)) AS ?totalCashFlow) WHERE {
      ?cf a wm:CashFlow .
      ?cf wm:cashFlowOfInvestor ?investor .
      ?cf wm:amount ?amount .
